export function getSurahByPage(page: number): SurahItem {
  // Find the surah that starts on or before this page
  let found = QURAN_SURAHS[0];
  for (const s of QURAN_SURAHS) {
    if (s.page <= page) {
      found = s;
    } else {
      break;
    }
  }
  return found;
}

export function getJuzByPage(page: number): JuzItem {
  let found = QURAN_JUZ[0];
  for (const j of QURAN_JUZ) {
    if (j.page <= page) {
      found = j;
    } else {
      break;
    }
  }
  return found;
}
